WITH ins AS (
  INSERT INTO ainventory.sources (name, kind, drive_file_id, drive_modified_at, import_batch, imported_at, note)
  VALUES ('Artificial Analysis Intelligence Index v5 — web pull 2026-11-12', 'aa-web', NULL, NULL,
          'fe02783b-046c-4401-bb35-8c529b216b8d', now(), 'AA Intelligence Index v5.0.1 web pull 2026-11-12 (Drew order; Supabase-only, no Drive — the 2026-11-02 aa-web route). Source: artificialanalysis.ai leaderboard + model pages, retrieved 2026-11-12 ~20:09-20:11 UTC. Loaded into this batch: NEW MODEL Gemini 4 Hydrogen (4 measured AA|v5 rows); Gemini 4 Carbon low/medium measured + high refreshed + xhigh ESTIMATED (|estimated key flag); Gemini 4 Argon high refreshed (II 50.4, $9.95/task) + low/medium/xhigh ESTIMATED; Gemini 3.8 Flash v5 refreshed to one-decimal values (22.5/30.1/30.8) + xhigh ESTIMATED; Claude Sonnet 5.5 + Opus 5.5 v5 refreshed to one-decimal values (Sonnet low config new); Gemini 2.5 family on PREVIOUS index versions only (Pro + Flash-Thinking keyed AA|v4.1, new Benchmark_Versions row; Flash + Flash-Lite keyed AA|v4.3.2) — old-scale, never comparable with v5. measurement_events: the 199 workbook-import events of batch 8152e746 carried forward under this batch (closing the post-2026-10-26 event gap), current configs refreshed/added for measured v5 rows, versioned 5.0.1 + previous-version events added; estimates carry NO workbook-import events (not measurements). ingest_batches registry row created for this batch (the FK home for the event/price loads). sheet-backfill mirror (code#4401): 15 events refreshed + 11 new v5 events under a follow-on batch record. price_events appended for the 9 dataset models (AA list prices). Drive workbook unchanged; a future workbook re-import supersedes this batch. Full record: Maintenance_Log 2026-11-12.')
  RETURNING id)
INSERT INTO _src SELECT id FROM ins;

